            if (!wrap) return;
            const wrapRect = wrap.getBoundingClientRect();
            const vhCenter = window.innerHeight / 2;
            const padding = 16;
            const minY = wrapRect.top + padding;
            const maxY = wrapRect.bottom - padding;
